function Navbar() {
  return (
    <nav className="w-full bg-green-300 text-white p-7 shadow-md mb-6 flex justify-between items-center rounded-b-2xl cursor-pointer">
      <h2 className="text-2xl font-bold">My Gallery</h2>
      <ul className="flex gap-6 text-lg">
        <li className="hover:underline cursor-pointer">Home</li>
        <li className="hover:underline cursor-pointer">Gallery</li>
        <li className="hover:underline cursor-pointer">Contact</li>
      </ul>
    </nav>
  );
}
export default Navbar;
